describe('buildWindowsAgentHookCurlPostCommand', () => {
  it('posts form fields via curl.exe and reads the payload from stdin', () => {
    const command = buildWindowsAgentHookCurlPostCommand('codex')

    // Why: the fast path must not spawn a second PowerShell; that startup cost
    // is the regression this replaces.
    expect(command).not.toMatch(/powershell/i)
    expect(command).toContain('%SystemRoot%\\System32\\curl.exe')
    expect(command).toContain('http://127.0.0.1:%ORCA_AGENT_HOOK_PORT%/hook/codex')
    expect(command).toContain('-H "Content-Type: application/x-www-form-urlencoded"')
    expect(command).toContain('-H "X-Orca-Agent-Hook-Token: %ORCA_AGENT_HOOK_TOKEN%"')
    expect(command).toContain('--data-urlencode "paneKey=%ORCA_PANE_KEY%"')
    expect(command).toContain('--data-urlencode "worktreeId=%ORCA_WORKTREE_ID%"')
    // Why: `payload@-` makes curl read raw bytes from stdin and urlencode them,
    // so UTF-8 prompts survive without a code-page conversion.
    expect(command).toContain('--data-urlencode "payload@-"')
    // Why: same dead-listener bound as the POSIX hook so a stalled server can't
    // hold up the agent.
    expect(command).toContain('--connect-timeout 0.5 --max-time 1.5')
  })

  it('targets the requested hook source endpoint', () => {
    expect(buildWindowsAgentHookCurlPostCommand('grok')).toContain('/hook/grok')
  })
})

import { describe, expect, it } from 'vitest'
import {
  resolveSourceControlCommitAreaPrimaryActionDecision,
  resolveSourceControlPrimaryActionDecision,
  type SourceControlPrimaryActionDecisionInputs
} from './source-control-primary-action-decision'

function inputs(
  overrides: Partial<SourceControlPrimaryActionDecisionInputs> = {}
): SourceControlPrimaryActionDecisionInputs {
  return {
    stagedCount: 0,
    hasUnstagedChanges: false,
    hasStageableChanges: false,
    hasPartiallyStagedChanges: false,
    hasMessage: false,
    hasUnresolvedConflicts: false,
    isCommitting: false,
    isRemoteOperationActive: false,
    upstreamStatus: undefined,
    ...overrides
  }
}

describe('source-control primary action decision', () => {
  it('returns Stage All for a dirty tree before remote actions', () => {
    const result = resolveSourceControlCommitAreaPrimaryActionDecision(
      inputs({
        hasUnstagedChanges: true,
        hasStageableChanges: true,
        upstreamStatus: { hasUpstream: true, ahead: 0, behind: 4 }
      })
    )
    expect(result.kind).toBe('stage')
    expect(result.titleIntent).toBe('stage_all_changes')
    expect(result.disabled).toBe(false)
  })

  it('returns enabled Commit for staged changes with a message', () => {
    const result = resolveSourceControlCommitAreaPrimaryActionDecision(
      inputs({ stagedCount: 2, hasMessage: true })
    )
    expect(result).toMatchObject({
      kind: 'commit',
      titleIntent: 'commit_staged_changes',
      disabled: false
    })
  })

  it('blocks commits while unresolved conflicts exist', () => {
    const result = resolveSourceControlCommitAreaPrimaryActionDecision(
      inputs({ stagedCount: 1, hasMessage: true, hasUnresolvedConflicts: true })
    )
    expect(result).toMatchObject({
      kind: 'commit',
      titleIntent: 'resolve_conflicts_before_commit',
      disabled: true
    })
  })

  it('returns remote push, pull, and sync decisions for clean tracked branches', () => {
    expect(
      resolveSourceControlCommitAreaPrimaryActionDecision(
        inputs({ upstreamStatus: { hasUpstream: true, ahead: 2, behind: 0 } })
      )
    ).toMatchObject({ kind: 'push', titleIntent: 'push_count', count: 2 })
    expect(
      resolveSourceControlCommitAreaPrimaryActionDecision(
        inputs({ upstreamStatus: { hasUpstream: true, ahead: 0, behind: 3 } })
      )
    ).toMatchObject({ kind: 'pull', titleIntent: 'pull_count', count: 3 })
    expect(
      resolveSourceControlCommitAreaPrimaryActionDecision(
        inputs({ upstreamStatus: { hasUpstream: true, ahead: 2, behind: 3 } })
      )
    ).toMatchObject({ kind: 'sync', titleIntent: 'sync_counts', ahead: 2, behind: 3 })
  })

  it('returns Publish Branch for clean unpublished branches with a current branch', () => {
    const result = resolveSourceControlCommitAreaPrimaryActionDecision(
      inputs({
        upstreamStatus: { hasUpstream: false, ahead: 0, behind: 0 },
        hasCurrentBranch: true
      })
    )
    expect(result).toMatchObject({
      kind: 'publish',
      titleIntent: 'publish_branch',
      disabled: false
    })
  })

  it('blocks unpublished branch publishing when HEAD is detached', () => {
    const result = resolveSourceControlCommitAreaPrimaryActionDecision(
      inputs({
        upstreamStatus: { hasUpstream: false, ahead: 0, behind: 0 },
        hasCurrentBranch: false
      })
    )
    expect(result).toMatchObject({
      kind: 'commit',
      titleIntent: 'checkout_branch_before_publish',
      disabled: true
    })
  })

  it('mirrors in-flight remote operation semantics', () => {
    const result = resolveSourceControlCommitAreaPrimaryActionDecision(
      inputs({
        isRemoteOperationActive: true,
        inFlightRemoteOpKind: 'pull',
        upstreamStatus: { hasUpstream: true, ahead: 3, behind: 0 }
      })
    )
    expect(result).toMatchObject({
      kind: 'pull',
      labelIntent: 'pull',
      titleIntent: 'action_in_progress',
      disabled: true
    })
  })

  it('marks patch-equivalent diverged branches as force-push-with-lease decisions', () => {
    const result = resolveSourceControlCommitAreaPrimaryActionDecision(
      inputs({
        branchCommitsAhead: 4,
        upstreamStatus: {
          hasUpstream: true,
          upstreamName: 'origin/feature',
          ahead: 14,
          behind: 3,
          behindCommitsArePatchEquivalent: true
        }
      })
    )
    expect(result).toMatchObject({
      kind: 'push',
      labelIntent: 'force_push',
      titleIntent: 'force_push_with_lease',
      requiresForceWithLease: true,
      count: 4,
      upstreamName: 'origin/feature'
    })
  })

  it('keeps review creation out of commit-area decisions', () => {
    const input = inputs({
      upstreamStatus: { hasUpstream: true, ahead: 0, behind: 0 },
      hostedReviewCreation: {
        provider: 'gitlab',
        review: null,
        canCreate: true,
        blockedReason: null,
        nextAction: null
      }
    })
    expect(resolveSourceControlPrimaryActionDecision(input).kind).toBe('create_pr')
    expect(resolveSourceControlCommitAreaPrimaryActionDecision(input).kind).toBe('commit')
  })

  it('returns disabled create review while hosted-review creation eligibility is loading', () => {
    const result = resolveSourceControlPrimaryActionDecision(
      inputs({
        upstreamStatus: { hasUpstream: true, ahead: 0, behind: 0 },
        hostedReviewCreation: {
          provider: 'gitlab',
          review: null,
          canCreate: false,
          blockedReason: null,
          nextAction: null
        },
        isHostedReviewCreationLoading: true
      })
    )
    expect(result).toMatchObject({
      kind: 'create_pr',
      titleIntent: 'checking_review_creation',
      disabled: true
    })
  })
})

import type { Page } from '@stablyai/playwright-test'
import { expect } from './helpers/orca-app'
import { ensureTerminalVisible } from './helpers/store'
import {
  getTerminalContent,
  splitActiveTerminalPane,
  waitForActiveTerminalManager,
  waitForPaneIdentitySnapshot
} from './helpers/terminal'

export type TerminalLoadPane = {
  paneKey: string
  ptyId: string
}

export async function focusActiveTerminalInput(page: Page): Promise<void> {
  await page.evaluate(() => {
    const store = window.__store
    const state = store?.getState()
    const worktreeId = state?.activeWorktreeId
    const tabId =
      state?.activeTabType === 'terminal'
        ? state.activeTabId
        : worktreeId
          ? (state?.activeTabIdByWorktree?.[worktreeId] ?? null)
          : null
    const manager = tabId ? window.__paneManagers?.get(tabId) : null
    const pane = manager?.getActivePane?.() ?? manager?.getPanes?.()[0] ?? null
    const textarea = pane?.container.querySelector<HTMLTextAreaElement>('.xterm-helper-textarea')
    if (!pane || !textarea) {
      throw new Error('Active terminal input is unavailable')
    }
    pane.terminal.focus()
    textarea.focus()
  })
}

export async function focusPane(page: Page, paneKey: string): Promise<void> {
  const separator = paneKey.indexOf(':')
  const tabId = paneKey.slice(0, separator)
  const leafId = paneKey.slice(separator + 1)
  await page.evaluate(
    ({ tabId, leafId }) => {
      const manager = window.__paneManagers?.get(tabId)
      const pane = manager?.getPanes?.().find((candidate) => candidate.leafId === leafId)
      if (!manager || !pane) {
        throw new Error(`Unable to focus pane ${tabId}:${leafId}`)
      }
      manager.setActivePane?.(pane.id, { focus: true })
    },
    { tabId, leafId }
  )
}

export async function ensureActiveWorktreePaneLoad(
  page: Page,
  paneCount: number
): Promise<TerminalLoadPane[]> {
  await ensureTerminalVisible(page)
  await waitForActiveTerminalManager(page, 30_000)
  let snapshot = await waitForPaneIdentitySnapshot(page, 1)
  while (snapshot.panes.length < paneCount) {
    await splitActiveTerminalPane(page, snapshot.panes.length % 2 === 0 ? 'horizontal' : 'vertical')
    snapshot = await waitForPaneIdentitySnapshot(page, snapshot.panes.length + 1)
  }
  return snapshot.panes.slice(0, paneCount).map((pane) => ({
    paneKey: `${snapshot.tabId}:${pane.leafId}`,
    ptyId: pane.ptyId ?? ''
  }))
}

export async function waitForMarkerLatency(
  page: Page,
  marker: string,
  timeoutMs: number
): Promise<number> {
  const start = performance.now()
  while (performance.now() - start < timeoutMs) {
    if ((await getTerminalContent(page, 12_000)).includes(marker)) {
      return performance.now() - start
    }
    await page.waitForTimeout(5)
  }
  throw new Error(`Timed out waiting for terminal marker ${marker}`)
}

export async function getTerminalContentForPtyId(
  page: Page,
  ptyId: string,
  charLimit = 12_000
): Promise<string> {
  return page.evaluate(
    ({ ptyId, charLimit }) => {
      for (const manager of window.__paneManagers?.values() ?? []) {
        for (const pane of manager.getPanes?.() ?? []) {
          if (pane.container?.dataset?.ptyId === ptyId) {
            return (pane.serializeAddon?.serialize?.() ?? '').slice(-charLimit)
          }
        }
      }
      return ''
    },
    { ptyId, charLimit }
  )
}

export async function waitForTerminalOutputForPtyId(
  page: Page,
  ptyId: string,
  expected: string,
  timeoutMs: number
): Promise<void> {
  await expect
    .poll(async () => (await getTerminalContentForPtyId(page, ptyId)).includes(expected), {
      timeout: timeoutMs,
      message: `Terminal PTY ${ptyId} did not contain "${expected}"`
    })
    .toBe(true)
}

