import { describe, expect, it, vi } from 'vitest'
import { makePaneKey } from '../../shared/stable-pane-id'
import { AgentHookServer, PANE_KEY_ALIASES_MAX } from './server'

const SOURCE = makePaneKey('tab-source', '11111111-1111-4111-8111-111111111111')
const TARGET = makePaneKey('tab-target', '22222222-2222-4222-8222-222222222222')
const FINAL = makePaneKey('tab-final', '33333333-3333-4333-8333-333333333333')
const SIBLING = makePaneKey('tab-target', '44444444-4444-4444-8444-444444444444')

describe('AgentHookServer pane authority', () => {
  it('keeps physical hooks routed after the source tab closes and suppresses them after owner retire', () => {
    const server = new AgentHookServer()
    server.ingestTerminalStatus({
      paneKey: SOURCE,
      tabId: 'tab-source',
      worktreeId: 'wt-1',
      payload: { state: 'working', prompt: 'source' }
    })

    server.transferPaneAuthority(SOURCE, TARGET, 'pty-1')
    server.dropStatusEntriesByTabPrefix('tab-source')
    server.ingestTerminalStatus({
      paneKey: SOURCE,
      tabId: 'tab-source',
      worktreeId: 'wt-1',
      payload: { state: 'working', prompt: 'after source close' }
    })

    expect(server.getStatusSnapshot()).toEqual([
      expect.objectContaining({
        paneKey: TARGET,
        tabId: 'tab-target',
        prompt: 'after source close'
      })
    ])

    server.ingestTerminalStatus({
      paneKey: SIBLING,
      tabId: 'tab-target',
      worktreeId: 'wt-1',
      payload: { state: 'working', prompt: 'sibling' }
    })
    server.retirePaneAuthority(TARGET)
    server.ingestTerminalStatus({
      paneKey: SOURCE,
      tabId: 'tab-source',
      worktreeId: 'wt-1',
      payload: { state: 'done', prompt: 'too late' }
    })

    expect(server.getStatusSnapshot()).toEqual([
      expect.objectContaining({ paneKey: SIBLING, prompt: 'sibling' })
    ])
  })

  it('persists one physical alias while chained transfers advance its owner', () => {
    const server = new AgentHookServer()
    const listener = vi.fn()
    server.setPaneKeyAliasPersistenceListener(listener)

    server.transferPaneAuthority(SOURCE, TARGET, 'pty-1', 10)
    server.transferPaneAuthority(TARGET, FINAL, 'pty-1', 20)

    expect(listener).toHaveBeenLastCalledWith([
      {
        legacyPaneKey: SOURCE,
        stablePaneKey: FINAL,
        ptyId: 'pty-1',
        updatedAt: 20
      }
    ])
  })

  it('requires live PTY ownership for a first transfer and trusts the chained alias afterward', () => {
    const server = new AgentHookServer()

    server.ingestTerminalStatus({
      paneKey: SOURCE,
      tabId: 'tab-source',
      worktreeId: 'wt-1',
      payload: { state: 'working', prompt: 'unverified source' }
    })

    expect(server.canTransferPaneAuthority(SOURCE, undefined, () => false)).toBe(false)
    expect(server.canTransferPaneAuthority(SOURCE, 'pty-1', () => false)).toBe(false)
    expect(
      server.canTransferPaneAuthority(SOURCE, 'pty-1', (paneKey, ptyId) => {
        return paneKey === SOURCE && ptyId === 'pty-1'
      })
    ).toBe(true)

    server.transferPaneAuthority(SOURCE, TARGET, 'pty-1')
    expect(server.canTransferPaneAuthority(TARGET, undefined, () => false)).toBe(true)
    expect(server.canTransferPaneAuthority(TARGET, 'pty-1', () => false)).toBe(true)
    expect(server.canTransferPaneAuthority(TARGET, 'other-pty', () => false)).toBe(false)
  })

  it('does not treat registered or restored aliases as verified authority', () => {
    const registered = new AgentHookServer()
    registered.registerPaneKeyAlias('tab-source:0', SOURCE, 'pty-1')

    expect(registered.canTransferPaneAuthority(SOURCE, undefined, () => false)).toBe(false)
    expect(registered.canTransferPaneAuthority(SOURCE, 'pty-1', () => false)).toBe(false)
    expect(
      registered.canTransferPaneAuthority(SOURCE, 'pty-1', (paneKey, ptyId) => {
        return paneKey === 'tab-source:0' && ptyId === 'pty-1'
      })
    ).toBe(true)

    const restored = new AgentHookServer()
    restored.transferPaneAuthority(SOURCE, TARGET, 'pty-1', 10, { authorityVerified: false })
    expect(restored.canTransferPaneAuthority(TARGET, undefined, () => false)).toBe(false)
    expect(restored.canTransferPaneAuthority(TARGET, 'pty-1', () => false)).toBe(false)
    expect(
      restored.canTransferPaneAuthority(TARGET, 'pty-1', (paneKey, ptyId) => {
        return paneKey === TARGET && ptyId === 'pty-1'
      })
    ).toBe(true)
    restored.transferPaneAuthority(TARGET, FINAL, 'pty-1', 20)
    expect(restored.canTransferPaneAuthority(FINAL, undefined, () => false)).toBe(true)
  })

  it('prefers a spawn-verified legacy alias over an earlier migration fallback', () => {
    const server = new AgentHookServer()
    server.registerPaneKeyAlias('tab-source:0', SOURCE, 'pty-1')
    server.registerPaneKeyAlias('tab-source:1', SOURCE, 'pty-1', 20, {
      authorityVerified: true
    })

    expect(server.canTransferPaneAuthority(SOURCE, undefined, () => false)).toBe(true)
    expect(server.canTransferPaneAuthority(SOURCE, 'pty-1', () => false)).toBe(true)
  })

  it('bounds persisted aliases by evicting the oldest authority', () => {
    const server = new AgentHookServer()
    const listener = vi.fn()
    server.setPaneKeyAliasPersistenceListener(listener)

    for (let index = 0; index <= PANE_KEY_ALIASES_MAX; index += 1) {
      const suffix = index.toString(16).padStart(12, '0')
      server.transferPaneAuthority(
        makePaneKey(`source-${index}`, `00000000-0000-4000-8000-${suffix}`),
        makePaneKey(`target-${index}`, `10000000-0000-4000-8000-${suffix}`),
        `pty-${index}`,
        index + 1
      )
    }

    const persisted = listener.mock.calls.at(-1)?.[0]
    expect(persisted).toHaveLength(PANE_KEY_ALIASES_MAX)
    expect(persisted).not.toEqual(
      expect.arrayContaining([
        expect.objectContaining({ legacyPaneKey: expect.stringContaining('source-0:') })
      ])
    )
  })
})

import { describe, expect, it } from 'vitest'
import { planSourceControlAgentActionLaunch } from './source-control-agent-action-plan'

describe('planSourceControlAgentActionLaunch', () => {
  it('rejects disabled agents', () => {
    expect(
      planSourceControlAgentActionLaunch({
        agent: 'codex',
        commandInput: 'Fix checks',
        promptDelivery: 'submit-after-ready',
        detectedAgents: ['codex'],
        disabledAgents: ['codex'],
        platform: 'darwin'
      })
    ).toEqual({ ok: false, error: 'The selected agent is disabled in Settings.' })
  })

  it('rejects agents not detected on the current host', () => {
    expect(
      planSourceControlAgentActionLaunch({
        agent: 'claude',
        commandInput: 'Fix checks',
        promptDelivery: 'submit-after-ready',
        detectedAgents: ['codex'],
        platform: 'linux'
      })
    ).toEqual({ ok: false, error: 'The selected agent was not detected on this workspace host.' })
  })

  it('mirrors submit-after-ready delivery without embedding the prompt in the command', () => {
    const result = planSourceControlAgentActionLaunch({
      agent: 'codex',
      commandInput: 'Fix checks',
      promptDelivery: 'submit-after-ready',
      detectedAgents: ['codex'],
      platform: 'linux'
    })

    expect(result.ok && result.delivery).toBe('paste-submit')
    expect(result.ok && result.commandLabel).toBe('codex')
    expect(result.ok && result.summary).toContain('pastes and submits')
    expect(result.ok && result.caveat).toContain('PATH')
  })

  it('includes per-action CLI arguments in submit-after-ready launch plans', () => {
    const result = planSourceControlAgentActionLaunch({
      agent: 'codex',
      commandInput: 'Fix checks',
      agentArgs: '--model gpt-5.5',
      promptDelivery: 'submit-after-ready',
      detectedAgents: ['codex'],
      platform: 'linux'
    })

    expect(result.ok && result.commandLabel).toBe("codex '--model' 'gpt-5.5'")
  })

  it.each([
    {
      terminalWindowsShell: 'cmd.exe',
      expectedCommand: 'powershell.exe -NoProfile -EncodedCommand'
    },
    {
      terminalWindowsShell: 'git-bash',
      expectedCommand: 'ORCA_HERMES_STARTUP_QUERY'
    }
  ])(
    'uses $terminalWindowsShell quoting for Hermes source-control prompts',
    ({ terminalWindowsShell, expectedCommand }) => {
      const result = planSourceControlAgentActionLaunch({
        agent: 'hermes',
        commandInput: 'Review the change',
        promptDelivery: 'auto-submit',
        detectedAgents: ['hermes'],
        platform: 'win32',
        terminalWindowsShell
      })

      expect(result.ok && result.plan.launchCommand).toContain(expectedCommand)
      expect(result.ok && result.plan.env?.ORCA_HERMES_STARTUP_QUERY).toBe('Review the change')
    }
  )

  it('rejects invalid per-action CLI arguments', () => {
    expect(
      planSourceControlAgentActionLaunch({
        agent: 'codex',
        commandInput: 'Fix checks',
        agentArgs: '--model "unterminated',
        promptDelivery: 'submit-after-ready',
        detectedAgents: ['codex'],
        platform: 'linux'
      })
    ).toEqual({
      ok: false,
      error: 'CLI arguments are invalid: Unclosed quote in command template.'
    })
  })

  it('uses native draft launch when the selected agent supports it', () => {
    const result = planSourceControlAgentActionLaunch({
      agent: 'claude',
      commandInput: 'Fix checks',
      promptDelivery: 'draft',
      detectedAgents: ['claude'],
      platform: 'darwin'
    })

    expect(result.ok && result.delivery).toBe('draft-native')
    expect(result.ok && result.commandLabel).toContain('--prefill')
  })
})

import { describe, expect, it, vi } from 'vitest'
import { createAgentPaneAuthorityOwnership } from './agent-pane-authority-ownership'

describe('agent pane authority ownership', () => {
  it('accepts only the PTY bound to the physical local pane', () => {
    const ownsPty = createAgentPaneAuthorityOwnership({
      getPtyIdForPaneKey: (paneKey) => (paneKey === 'source-pane' ? 'pty-1' : undefined)
    })

    expect(ownsPty('source-pane', 'pty-1')).toBe(true)
    expect(ownsPty('source-pane', 'pty-forged')).toBe(false)
    expect(ownsPty('other-pane', 'pty-1')).toBe(false)
  })

  it('matches scoped and legacy runtime IDs to the authoritative terminal handle', () => {
    const getRuntimeTerminalHandleForPaneKey = vi.fn(() => 'terminal:one')
    const ownsPty = createAgentPaneAuthorityOwnership({
      getRuntimeTerminalHandleForPaneKey
    })

    expect(ownsPty('source-pane', 'remote:terminal:one')).toBe(true)
    expect(ownsPty('source-pane', 'remote:env-1@@terminal%3Aone')).toBe(true)
    expect(ownsPty('source-pane', 'remote:env-1@@other')).toBe(false)
    expect(ownsPty('source-pane', 'remote:env-1@@%E0%A4%A')).toBe(false)
    expect(ownsPty('source-pane', 'remote:@@terminal%3Aone')).toBe(false)
    expect(ownsPty('source-pane', 'remote:%20@@terminal%3Aone')).toBe(false)
    expect(ownsPty('source-pane', 'remote:env-1@@')).toBe(false)
    expect(ownsPty('source-pane', 'remote:env-1@@terminal:one')).toBe(false)
    expect(ownsPty('source-pane', 'remote:terminal%3Aone')).toBe(false)
  })
})

import { describe, expect, it } from 'vitest'
import {
  clampMarkupScale,
  dataUrlByteLength,
  effectiveMarkupScale,
  markupCanvasSize,
  MARKUP_DOWNSCALE_STEPS
} from './markup-screenshot-compose'

describe('clampMarkupScale', () => {
  it('keeps sane scales and clamps to [1, 4]', () => {
    expect(clampMarkupScale(2)).toBe(2)
    expect(clampMarkupScale(0.5)).toBe(1)
    expect(clampMarkupScale(10)).toBe(4)
  })

  it('guards against non-finite / non-positive values', () => {
    expect(clampMarkupScale(0)).toBe(1)
    expect(clampMarkupScale(-3)).toBe(1)
    expect(clampMarkupScale(Number.NaN)).toBe(1)
  })
})

describe('markupCanvasSize', () => {
  it('sizes the output to the content box times the (clamped) scale', () => {
    expect(markupCanvasSize(800, 600, 2)).toEqual({ width: 1600, height: 1200 })
    expect(markupCanvasSize(800, 600, 0.5)).toEqual({ width: 800, height: 600 })
  })

  it('keeps the composite within the pixel budget (never over)', () => {
    // A large HiDPI pane: 4000×3000 CSS × dpr 2 = 48M px > the ~33.55M (32×1024×1024) ceiling.
    const maxPixels = 32 * 1024 * 1024
    const size = markupCanvasSize(4000, 3000, 2, maxPixels)
    expect(size.width * size.height).toBeLessThanOrEqual(maxPixels)
    // Aspect ratio is preserved (one uniform scale).
    expect(size.width / size.height).toBeCloseTo(4000 / 3000, 3)
  })
})

describe('effectiveMarkupScale', () => {
  it('returns the clamped scale when the composite fits the pixel budget', () => {
    expect(effectiveMarkupScale(800, 600, 2, 32 * 1024 * 1024)).toBe(2)
  })

  it('reduces the scale so area stays within the pixel budget', () => {
    const scale = effectiveMarkupScale(4000, 3000, 2, 32 * 1024 * 1024)
    expect(scale).toBeLessThan(2)
    expect(4000 * scale * (3000 * scale)).toBeLessThanOrEqual(32 * 1024 * 1024 + 1)
  })

  it('defaults to the clamped scale with no pixel budget', () => {
    expect(effectiveMarkupScale(3840, 2160, 2)).toBe(2)
  })
})

describe('dataUrlByteLength', () => {
  it('decodes the base64 payload size', () => {
    // "hi" -> base64 "aGk=" (1 pad char) -> 2 bytes
    expect(dataUrlByteLength('data:image/png;base64,aGk=')).toBe(2)
    // "man" -> "bWFu" (no padding) -> 3 bytes
    expect(dataUrlByteLength('data:image/png;base64,bWFu')).toBe(3)
  })

  it('returns 0 for a malformed data url', () => {
    expect(dataUrlByteLength('not-a-data-url')).toBe(0)
  })
})

describe('compose budget plans', () => {
  it('tries full size first, then shrinks (PNG only, descending)', () => {
    expect(MARKUP_DOWNSCALE_STEPS[0]).toBe(1)
    expect([...MARKUP_DOWNSCALE_STEPS]).toEqual([...MARKUP_DOWNSCALE_STEPS].sort((a, b) => b - a))
    expect(MARKUP_DOWNSCALE_STEPS.every((s) => s > 0 && s <= 1)).toBe(true)
  })
})

import { describe, expect, it } from 'vitest'
import { shouldShowMobileEmulatorAgentSetupGuide } from './mobile-emulator-agent-setup-visibility'

describe('shouldShowMobileEmulatorAgentSetupGuide', () => {
  it('shows while setup is incomplete on an active pane', () => {
    expect(
      shouldShowMobileEmulatorAgentSetupGuide({
        dismissed: false,
        initialProbeComplete: true,
        isActive: true,
        statusReady: true
      })
    ).toBe(true)
  })

  it('stays visible when setup is complete until the user dismisses it', () => {
    expect(
      shouldShowMobileEmulatorAgentSetupGuide({
        dismissed: false,
        initialProbeComplete: true,
        isActive: true,
        statusReady: true
      })
    ).toBe(true)
  })

  it('hides before the first probe completes or after dismissal', () => {
    expect(
      shouldShowMobileEmulatorAgentSetupGuide({
        dismissed: false,
        initialProbeComplete: false,
        isActive: true,
        statusReady: false
      })
    ).toBe(false)
    expect(
      shouldShowMobileEmulatorAgentSetupGuide({
        dismissed: true,
        initialProbeComplete: true,
        isActive: true,
        statusReady: true
      })
    ).toBe(false)
  })

  it('stays visible while Re-check or focus refresh reloads probes', () => {
    expect(
      shouldShowMobileEmulatorAgentSetupGuide({
        dismissed: false,
        initialProbeComplete: true,
        isActive: true,
        statusReady: false
      })
    ).toBe(true)
  })

  it('hides on inactive panes pre-mounted for split safety', () => {
    expect(
      shouldShowMobileEmulatorAgentSetupGuide({
        dismissed: false,
        initialProbeComplete: true,
        isActive: false,
        statusReady: true
      })
